-- 연결 CSV의 10개 컬럼을 그대로 적재한다. 빈 이동 유형도 원본대로 빈 문자열로 저장한다.
ON CONFLICT (from_node_id, to_node_id, move_type) DO UPDATE SET
    from_building = EXCLUDED.from_building, from_floor = EXCLUDED.from_floor, from_photo = EXCLUDED.from_photo, to_building = EXCLUDED.to_building, to_floor = EXCLUDED.to_floor, to_photo = EXCLUDED.to_photo, description = EXCLUDED.description;
